        typeof x !== 'number' || Number.isNaN(x)) {
      throw new RangeError('invalid search arguments');
    }
    return this._first(1, 0, this._length, lo, x);
  }

  get(i) {
    if (!Number.isInteger(i) || i < 0 || i >= this._length) {
      throw new RangeError('invalid index');
