    this._push(node, left, right);
    const middle = Math.floor((left + right) / 2);
    let result = 0;
    if (l < middle) result = Math.max(result, this._max(node * 2, left, middle, l, r));
    if (r > middle) result = Math.max(result, this._max(node * 2 + 1, middle, right, l, r));
